        return BadRequest(new { error = "Request body is required." });

    var mapping = new FrTrMapping(frId, request.TrIds ?? Array.Empty<string>(), request.TestIds ?? Array.Empty<string>());
    try
    {
        await _requirements.UpsertMappingAsync(mapping, cancellationToken).ConfigureAwait(false);
    }
    catch (RequirementsNotFoundException ex)
    {
        _logger.LogError("{ExceptionDetail}", ex.ToString());
        return NotFound(new { error = ex.Message });
    }
    catch (ArgumentException ex)
    {
        _logger.LogError("{ExceptionDetail}", ex.ToString());
        return BadRequest(new { error = ex.Message });
    }

    return Ok(mapping);

private async Task<ActionResult<RequirementsBatchResult>> ExecuteBatchAsync(
    string operation,
    string? kind,
    RequirementsBatchEntries entries,
    Func<RequirementsBatchEntries, CancellationToken, Task<RequirementsBatchEntries>> executeAsync,
    CancellationToken cancellationToken)
{
    try
    {
        var result = await executeAsync(entries, cancellationToken).ConfigureAwait(false);
        return Ok(BuildBatchResult(operation, kind, result));
    }
    catch (RequirementsConflictException ex)
    {
        _logger.LogError("{ExceptionDetail}", ex.ToString());
        return Conflict(BuildBatchErrorResult(operation, kind, ex.Message));
    }
    catch (RequirementsNotFoundException ex)
    {
        _logger.LogError("{ExceptionDetail}", ex.ToString());
        return NotFound(BuildBatchErrorResult(operation, kind, ex.Message));
    }
    catch (ArgumentException ex)
    {
        _logger.LogError("{ExceptionDetail}", ex.ToString());
        return BadRequest(BuildBatchErrorResult(operation, kind, ex.Message));
    }
}

private static RequirementsBatchResult BuildBatchResult(string operation, string? kind, RequirementsBatchEntries entries)
{
    var items = new List<RequirementsBatchItem>();
    items.AddRange(entries.Functional.Select(entry => new RequirementsBatchItem { Kind = "fr", Id = entry.Id, Fr = entry }));
    items.AddRange(entries.Technical.Select(entry => new RequirementsBatchItem { Kind = "tr", Id = entry.Id, Tr = entry }));
    items.AddRange(entries.Testing.Select(entry => new RequirementsBatchItem { Kind = "test", Id = entry.Id, Test = entry }));

    return new RequirementsBatchResult
    {
        Success = true,
        Operation = operation,
        Kind = kind,
        Total = items.Count,
        Items = items
    };
}

private static RequirementsBatchResult BuildBatchErrorResult(string operation, string? kind, string error, int index = -1, string? id = null) =>
    new()
    {
        Success = false,
        Operation = operation,
        Kind = kind,
        Total = 0,
        Errors =
        [
            new RequirementsBatchError
            {
                Index = index,
                Kind = kind,
                Id = id,
                Error = error
            }
        ]
    };

private async Task<RequirementsBatchEntries> ResolveMixedUpdatesAsync(IReadOnlyList<UpdateRequirementBatchRecord> records, CancellationToken cancellationToken)
{
    var fr = new List<FrEntry>();
    var tr = new List<TrEntry>();
    var test = new List<TestEntry>();

    for (var i = 0; i < records.Count; i++)
    {
        var record = records[i];
        var id = RequireBatchId(record.Id, "requirement", i);
        switch (NormalizeRequirementKind(record.Kind, i))
        {
            case "fr":
                var existingFr = await _requirements.GetFrAsync(id, cancellationToken).ConfigureAwait(false)
                    ?? throw new RequirementsNotFoundException($"FR '{id}' was not found.");
                fr.Add(existingFr with
                {
                    Title = record.Title ?? existingFr.Title,
                    Body = record.Body ?? record.Description ?? existingFr.Body,
                    Priority = record.Priority ?? existingFr.Priority,
                    Status = record.Status ?? existingFr.Status,
                    Notes = record.Notes ?? existingFr.Notes,
                    AcceptanceCriteria = record.AcceptanceCriteria ?? existingFr.AcceptanceCriteria,
                    ScopeStartLayerKey = record.ScopeStartLayerKey ?? existingFr.ScopeStartLayerKey,
                    ScopeEndLayerKey = record.ScopeEndLayerKey ?? existingFr.ScopeEndLayerKey
                });
                break;
            case "tr":
                var existingTr = await _requirements.GetTrAsync(id, cancellationToken).ConfigureAwait(false)
                    ?? throw new RequirementsNotFoundException($"TR '{id}' was not found.");
                tr.Add(existingTr with
                {
                    Title = record.Title ?? existingTr.Title,
                    Body = record.Body ?? record.Description ?? existingTr.Body,
                    Priority = record.Priority ?? existingTr.Priority,
                    Status = record.Status ?? existingTr.Status,
                    Notes = record.Notes ?? existingTr.Notes,
                    AcceptanceCriteria = record.AcceptanceCriteria ?? existingTr.AcceptanceCriteria,
                    ScopeStartLayerKey = record.ScopeStartLayerKey ?? existingTr.ScopeStartLayerKey,
                    ScopeEndLayerKey = record.ScopeEndLayerKey ?? existingTr.ScopeEndLayerKey
                });
                break;
            case "test":
                var existingTest = await _requirements.GetTestAsync(id, cancellationToken).ConfigureAwait(false)
                    ?? throw new RequirementsNotFoundException($"TEST '{id}' was not found.");
                test.Add(existingTest with
                {
                    Title = record.Title ?? existingTest.Title,
                    Condition = record.Condition ?? record.Body ?? record.Description ?? existingTest.Condition,
                    Priority = record.Priority ?? existingTest.Priority,
                    Status = record.Status ?? existingTest.Status,
                    Notes = record.Notes ?? existingTest.Notes,
                    AcceptanceCriteria = record.AcceptanceCriteria ?? existingTest.AcceptanceCriteria,
                    ScopeStartLayerKey = record.ScopeStartLayerKey ?? existingTest.ScopeStartLayerKey,
                    ScopeEndLayerKey = record.ScopeEndLayerKey ?? existingTest.ScopeEndLayerKey
                });
                break;
        }
    }

    return new RequirementsBatchEntries(fr, tr, test);
}

private static string NormalizeRequirementKind(string? kind, int index)
{
    var normalized = (kind ?? string.Empty).Trim().ToLowerInvariant();
    return normalized switch
    {
        "fr" or "functional" => "fr",
        "tr" or "technical" => "tr",
        "test" or "testing" => "test",
        _ => throw new ArgumentException($"Record {index} has unsupported kind '{kind}'. Expected fr|tr|test.", nameof(kind))
    };
}

private static string RequireBatchId(string? id, string label, int index)
{
    if (string.IsNullOrWhiteSpace(id))
        throw new ArgumentException($"Record {index} is missing a {label} ID.", nameof(id));

    return id.Trim();
}

public async Task<RequirementsBatchEntries> UpdateBatchAsync(RequirementsBatchEntries entries, CancellationToken ct = default)
{
    ArgumentNullException.ThrowIfNull(entries);
    ValidateBatchEntries(entries);
    ValidateBatchUniqueIds(entries);

    await _writeLock.WaitAsync(ct).ConfigureAwait(false);
    try
    {
        await using var scope = CreateScope();
        var ctx = scope.Context;
        await EnsureBootstrappedAsync(ctx, ct).ConfigureAwait(false);
        await using var transaction = await ctx.Database.BeginTransactionAsync(ct).ConfigureAwait(false);

        var updates = new List<(RequirementEntity Row, RequirementBatchValue Value)>();
        foreach (var value in EnumerateBatch(entries))
        {
            var row = await FindRequirementAsync(ctx, value.Kind, value.Id, asTracking: true, ct).ConfigureAwait(false)
                ?? throw new RequirementsNotFoundException($"{value.Kind.ToUpperInvariant()} '{value.Id}' was not found.");
            _ = await ValidateRequirementScopeAsync(ctx, value.ScopeStartLayerKey, value.ScopeEndLayerKey, ct).ConfigureAwait(false);
            updates.Add((row, value));
        }

        var now = Now();
        foreach (var (row, value) in updates)
        {
            var requirementScope = await ValidateRequirementScopeAsync(ctx, value.ScopeStartLayerKey, value.ScopeEndLayerKey, ct).ConfigureAwait(false);
            row.Title = value.Title;
            row.Body = value.Body;
            row.Priority = NormalizePriority(value.Priority);
            row.Status = NormalizeStatus(value.Status);
            row.Notes = value.Notes;
            await SetCriteriaAsync(ctx, row, value.AcceptanceCriteria, ct).ConfigureAwait(false);
            row.ScopeStartLayerKey = requirementScope.Start;
            row.ScopeEndLayerKey = requirementScope.End;
            row.UpdatedAtUtc = now;
        }

        await ctx.SaveChangesAsync(ct).ConfigureAwait(false);
        await transaction.CommitAsync(ct).ConfigureAwait(false);

        var result = NormalizeBatchResult(entries, RequireWorkspaceId(ctx));
        await PublishBatchRequirementsChangeSafeAsync(ChangeEventActions.Updated, result, ct).ConfigureAwait(false);
        return result;
    }
    finally
    {
        _writeLock.Release();
    }
}

/// <inheritdoc />
public async Task<IReadOnlyList<FrTrMapping>> GetAllMappingsAsync(CancellationToken ct = default)
{
    await using var scope = CreateScope();
    await EnsureBootstrappedAsync(scope.Context, ct).ConfigureAwait(false);
    var links = await scope.Context.RequirementTraceabilityLinks
        .AsNoTracking()
        .OrderBy(x => x.FrId)
        .ThenBy(x => x.TargetKind)
        .ThenBy(x => x.TargetId)
        .ToListAsync(ct)
        .ConfigureAwait(false);

    return links
        .GroupBy(x => x.FrId, StringComparer.OrdinalIgnoreCase)
        .Select(group => new FrTrMapping(
            group.Key,
            group.Where(x => x.TargetKind == TrKind).Select(x => x.TargetId).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),
            group.Where(x => x.TargetKind == TestKind).Select(x => x.TargetId).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),
            group.First().WorkspaceId))
        .ToArray();
}

/// <inheritdoc />
public async Task<FrTrMapping?> GetMappingAsync(string frId, CancellationToken ct = default)
{
    ValidateId(frId, nameof(frId));
    // Filter to the requested FR server-side instead of materializing every
    // traceability link in the workspace and scanning in memory.
    var target = frId.Trim().ToUpperInvariant();
    await using var scope = CreateScope();
    await EnsureBootstrappedAsync(scope.Context, ct).ConfigureAwait(false);
    var links = await scope.Context.RequirementTraceabilityLinks
        .AsNoTracking()
        .Where(x => x.FrId.ToUpper() == target)
        .OrderBy(x => x.TargetKind)
        .ThenBy(x => x.TargetId)
        .ToListAsync(ct)
        .ConfigureAwait(false);
    if (links.Count == 0)
    {
        return null;
    }

    return new FrTrMapping(
        links[0].FrId,
        links.Where(x => x.TargetKind == TrKind).Select(x => x.TargetId).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),
        links.Where(x => x.TargetKind == TestKind).Select(x => x.TargetId).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),
        links[0].WorkspaceId);
}

/// <inheritdoc />
public async Task UpsertMappingAsync(FrTrMapping mapping, CancellationToken ct = default)
{
    ValidateMapping(mapping);
    var normalizedTrIds = NormalizeIds(mapping.TrIds);
    var normalizedTestIds = NormalizeIds(mapping.TestIds);

    await _writeLock.WaitAsync(ct).ConfigureAwait(false);
    try
    {
        await using var scope = CreateScope();
        var ctx = scope.Context;
        await EnsureBootstrappedAsync(ctx, ct).ConfigureAwait(false);
        await ValidateMappingTargetsAsync(ctx, mapping.FrId, normalizedTrIds, normalizedTestIds, ct).ConfigureAwait(false);

        var workspaceId = RequireWorkspaceId(ctx);
        var existingLinks = await ctx.RequirementTraceabilityLinks
            .IgnoreQueryFilters(SoftDeleteQueryFilter)
            .Where(x => x.WorkspaceId == workspaceId && x.FrId == mapping.FrId)
            .ToListAsync(ct)
            .ConfigureAwait(false);

        var timestamp = DateTimeOffset.UtcNow;
        var now = timestamp.ToString("O");
        var desiredKeys = normalizedTrIds
            .Select(trId => BuildTraceabilityLinkKey(TrKind, trId))
            .Concat(normalizedTestIds.Select(testId => BuildTraceabilityLinkKey(TestKind, testId)))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        foreach (var existingLink in existingLinks.Where(link => !desiredKeys.Contains(BuildTraceabilityLinkKey(link.TargetKind, link.TargetId))))
            MarkSoftDeleted(ctx, existingLink, timestamp, "requirements_mapping_replaced");

        foreach (var trId in normalizedTrIds)
            UpsertTraceabilityLink(ctx, existingLinks, workspaceId, mapping.FrId, TrKind, trId, now);
        foreach (var testId in normalizedTestIds)
            UpsertTraceabilityLink(ctx, existingLinks, workspaceId, mapping.FrId, TestKind, testId, now);

        await ctx.SaveChangesAsync(ct).ConfigureAwait(false);
        await PublishRequirementsChangeSafeAsync(ChangeEventActions.Updated, mapping.FrId, ct).ConfigureAwait(false);
    }
    finally
    {
        _writeLock.Release();
    }
}

private async Task<T> ExecuteMutationAsync<T>(
    string operationName,
    object operationBody,
    Func<CancellationToken, Task<T>> mutation,
    CancellationToken cancellationToken)
{
    if (TurnTransactionKeyserverScope.ShouldBypassCoordinator(_coordinator, operationName))
        return await mutation(cancellationToken).ConfigureAwait(false);

    var status = _coordinator!.GetStatus();
    if (status.Degraded)
        throw new RequirementsConflictException(string.IsNullOrWhiteSpace(status.Message)
            ? "Turn transaction coordinator is degraded."
            : status.Message);

    var requiresMutationTransactions = RequiresMutationTransactions(status);
    if (requiresMutationTransactions && _compensation is null)
        throw new RequirementsConflictException("Requirements storage does not support transaction rollback compensation.");

    T? mutationResult = default;
    var hasMutationResult = false;
    var transaction = BuildTransactionRequest(operationName, operationBody);
    var result = await _coordinator.ExecuteAsync(
            transaction,
            async ct =>
            {
                var snapshot = _compensation is null
                    ? null
                    : await _compensation.CaptureRequirementsSnapshotAsync(ct).ConfigureAwait(false);

                mutationResult = await mutation(ct).ConfigureAwait(false);
                hasMutationResult = true;

                return new TurnMutationResult
                {
                    Success = true,
                    ResultJson = JsonSerializer.Serialize(mutationResult, JsonOptions),
                    RollbackAsync = snapshot is not null
                        ? rollbackCt => _compensation!.RestoreRequirementsSnapshotAsync(snapshot, rollbackCt)
                        : null,
                };
            },
            cancellationToken)
        .ConfigureAwait(false);

    if (hasMutationResult && IsTransactionSuccess(result))
        return mutationResult!;

    throw ToTransactionFailure(operationName, result);

private object?[] BindArguments(
    ParameterInfo[] parameters,
    Dictionary<string, object?> arguments,
    CancellationToken cancellationToken)
{
    var boundArgs = new object?[parameters.Length];
    var nullabilityContext = new NullabilityInfoContext();

    for (int i = 0; i < parameters.Length; i++)
    {
        var parameter = parameters[i];

        // CancellationToken is always passed from the method parameter
        if (parameter.ParameterType == typeof(CancellationToken))
        {
            boundArgs[i] = cancellationToken;
            continue;
        }

        // Try to find matching argument (case-insensitive)
        var argKey = arguments.Keys.FirstOrDefault(k =>
            string.Equals(k, parameter.Name, StringComparison.OrdinalIgnoreCase));

        if (argKey is null)
        {
            // Check if parameter is optional
            if (parameter.HasDefaultValue)
            {
                boundArgs[i] = parameter.DefaultValue;
                continue;
            }

            // Required parameter missing
            throw new ArgumentException(
                $"Missing required parameter: {parameter.Name} (type: {parameter.ParameterType.Name})");
        }

        var argValue = arguments[argKey];

        // Get nullability info for the parameter
        var nullabilityInfo = nullabilityContext.Create(parameter);

        // Coerce argument to target type
        boundArgs[i] = CoerceArgument(argValue, parameter.ParameterType, parameter.Name, nullabilityInfo);
    }

    return boundArgs;
